module rtl_checker #(
    parameter int ADDR_W = 3,
    parameter int ID_W   = 1,
    parameter int LEN_W  = 1
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    input  logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    input  logic              s_axi_wready,

    input  logic [ID_W-1:0]   s_axi_bid,
    input  logic [1:0]        s_axi_bresp,
    input  logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    input  logic              s_axi_arready,

    input  logic [ID_W-1:0]   s_axi_rid,
    input  logic [31:0]       s_axi_rdata,
    input  logic [1:0]        s_axi_rresp,
    input  logic              s_axi_rlast,
    input  logic              s_axi_rvalid,
    input  logic              s_axi_rready
);
    function automatic logic desc_legal(input logic [2:0] a, input logic [2:0] sz,
                                        input logic [1:0] b, input logic lk,
                                        input logic ln);
        int ai;
        int li;
        int fin;
        begin
            ai  = a;
            li  = ln;
            fin = ai + 4 * li;
            desc_legal = (a[1:0] == 2'b00) && (sz == 3'd2) && (b == 2'b01) &&
                         (lk == 1'b0) && (fin < 8);
        end
    endfunction

    reg known = 1'b0;
    reg chk;
    reg [31:0] m0;
    reg [31:0] m1;

    int wst;
    reg [ID_W-1:0] wid;
    reg [2:0] waddr;
    int wlen;
    int wbeat;
    reg wlegal;
    reg werr;
    reg bwait;
    reg bpend;
    reg aw_lo;
    reg w_lo;

    int rs;
    reg [ID_W-1:0] ridc;
    reg [2:0] raddrc;
    int rlen;
    int rbeat;
    reg rlegal;
    reg [31:0] rsnap;
    reg rwait;
    reg rpend;
    reg ar_lo;

    reg [1:0] bexp;
    reg [1:0] rexp;
    reg [31:0] rdexp;
    reg rlexp;
    reg [31:0] tw;
    int widx;
    int ridx;
    reg wl_exp;
    reg lg;

    always @(posedge clk) begin
        chk   = known && !rst;
        bexp  = (werr || !wlegal) ? 2'b10 : 2'b00;
        rexp  = rlegal ? 2'b00 : 2'b10;
        rdexp = rlegal ? rsnap : 32'd0;
        rlexp = (rbeat >= rlen);

        // Reset suppresses ready signals
        assert(!rst || (!s_axi_awready && !s_axi_wready && !s_axi_arready));

        // Ready legality
        assert(!chk || wst == 0 || !s_axi_awready);
        assert(!chk || wst == 1 || !s_axi_wready);
        assert(!chk || rs == 0 || !s_axi_arready);

        // Ready throttling
        assert(!chk || !(wst == 0 && aw_lo) || s_axi_awready);
        assert(!chk || !(wst == 1 && w_lo) || s_axi_wready);
        assert(!chk || !(rs == 0 && ar_lo) || s_axi_arready);

        // B channel
        assert(!chk || wst == 2 || !s_axi_bvalid);
        assert(!chk || !(wst == 2 && bwait) || s_axi_bvalid);
        assert(!chk || !bpend || s_axi_bvalid);
        assert(!(chk && s_axi_bvalid && wst == 2) ||
               (s_axi_bid == wid && s_axi_bresp == bexp));

        // R channel
        assert(!chk || rs == 1 || !s_axi_rvalid);
        assert(!chk || !(rs == 1 && rwait) || s_axi_rvalid);
        assert(!chk || !rpend || s_axi_rvalid);
        assert(!(chk && s_axi_rvalid && rs == 1) ||
               (s_axi_rid == ridc && s_axi_rresp == rexp &&
                s_axi_rdata == rdexp && s_axi_rlast == rlexp));

        // Model update
        if (rst) begin
            known = 1'b1;
            wst = 0; rs = 0;
            m0 = 32'd0; m1 = 32'd0;
            bwait = 1'b0; bpend = 1'b0; aw_lo = 1'b0; w_lo = 1'b0;
            rwait = 1'b0; rpend = 1'b0; ar_lo = 1'b0;
            wid = {ID_W{1'b0}}; waddr = 3'd0; wlen = 0; wbeat = 0;
            wlegal = 1'b0; werr = 1'b0;
            ridc = {ID_W{1'b0}}; raddrc = 3'd0; rlen = 0; rbeat = 0;
            rlegal = 1'b0; rsnap = 32'd0;
        end else if (known) begin
            aw_lo = (wst == 0) && !s_axi_awready;
            w_lo  = (wst == 1) && !s_axi_wready;
            ar_lo = (rs == 0) && !s_axi_arready;
            bpend = s_axi_bvalid && !s_axi_bready;
            rpend = s_axi_rvalid && !s_axi_rready;

            // read side first (snapshots use memory before this edge)
            if (rs == 0) begin
                if (s_axi_arvalid && s_axi_arready) begin
                    lg = desc_legal(s_axi_araddr, s_axi_arsize, s_axi_arburst,
                                    s_axi_arlock, s_axi_arlen[0]);
                    ridc = s_axi_arid;
                    raddrc = s_axi_araddr;
                    rlen = s_axi_arlen;
                    rbeat = 0;
                    rlegal = lg;
                    rs = 1;
                    rwait = 1'b0;
                    rsnap = lg ? (s_axi_araddr[2] ? m1 : m0) : 32'd0;
                end
            end else begin
                if (s_axi_rvalid && s_axi_rready) begin
                    if (rbeat >= rlen) begin
                        rs = 0;
                        rwait = 1'b0;
                    end else begin
                        ridx = (raddrc >> 2) + rbeat + 1;
                        rbeat = rbeat + 1;
                        rwait = 1'b0;
                        rsnap = rlegal ? ((ridx == 1) ? m1 : m0) : 32'd0;
                    end
                end else begin
                    rwait = !s_axi_rvalid;
                end
            end

            // write side
            if (wst == 0) begin
                if (s_axi_awvalid && s_axi_awready) begin
                    wid = s_axi_awid;
                    waddr = s_axi_awaddr;
                    wlen = s_axi_awlen;
                    wbeat = 0;
                    wlegal = desc_legal(s_axi_awaddr, s_axi_awsize, s_axi_awburst,
                                        s_axi_awlock, s_axi_awlen[0]);
                    werr = 1'b0;
                    wst = 1;
                    bwait = 1'b0;
                end
            end else if (wst == 1) begin
                if (s_axi_wvalid && s_axi_wready) begin
                    wl_exp = (wbeat >= wlen) ? 1'b1 : 1'b0;
                    if (s_axi_wlast != wl_exp) werr = 1'b1;
                    if (wlegal) begin
                        widx = (waddr >> 2) + wbeat;
                        tw = (widx == 1) ? m1 : m0;
                        for (int i = 0; i < 4; i = i + 1) begin
                            if (s_axi_wstrb[i]) tw[8*i +: 8] = s_axi_wdata[8*i +: 8];
                        end
                        if (widx == 1) m1 = tw; else m0 = tw;
                    end
                    if (wbeat >= wlen) begin
                        wst = 2;
                        bwait = 1'b0;
                    end else begin
                        wbeat = wbeat + 1;
                    end
                end
            end else begin
                if (s_axi_bvalid && s_axi_bready) begin
                    wst = 0;
                    bwait = 1'b0;
                end else begin
                    bwait = !s_axi_bvalid;
                end
            end
        end
    end
endmodule

module rtl_checker #(
    parameter int ADDR_W = 3,
    parameter int ID_W   = 1,
    parameter int LEN_W  = 1
) (
    input  logic              clk,
    input  logic              rst,

    input  logic [ID_W-1:0]   s_axi_awid,
    input  logic [ADDR_W-1:0] s_axi_awaddr,
    input  logic [LEN_W-1:0]  s_axi_awlen,
    input  logic [2:0]        s_axi_awsize,
    input  logic [1:0]        s_axi_awburst,
    input  logic              s_axi_awlock,
    input  logic [3:0]        s_axi_awcache,
    input  logic [2:0]        s_axi_awprot,
    input  logic [3:0]        s_axi_awqos,
    input  logic [3:0]        s_axi_awregion,
    input  logic              s_axi_awvalid,
    input  logic              s_axi_awready,

    input  logic [31:0]       s_axi_wdata,
    input  logic [3:0]        s_axi_wstrb,
    input  logic              s_axi_wlast,
    input  logic              s_axi_wvalid,
    input  logic              s_axi_wready,

    input  logic [ID_W-1:0]   s_axi_bid,
    input  logic [1:0]        s_axi_bresp,
    input  logic              s_axi_bvalid,
    input  logic              s_axi_bready,

    input  logic [ID_W-1:0]   s_axi_arid,
    input  logic [ADDR_W-1:0] s_axi_araddr,
    input  logic [LEN_W-1:0]  s_axi_arlen,
    input  logic [2:0]        s_axi_arsize,
    input  logic [1:0]        s_axi_arburst,
    input  logic              s_axi_arlock,
    input  logic [3:0]        s_axi_arcache,
    input  logic [2:0]        s_axi_arprot,
    input  logic [3:0]        s_axi_arqos,
    input  logic [3:0]        s_axi_arregion,
    input  logic              s_axi_arvalid,
    input  logic              s_axi_arready,

    input  logic [ID_W-1:0]   s_axi_rid,
    input  logic [31:0]       s_axi_rdata,
    input  logic [1:0]        s_axi_rresp,
    input  logic              s_axi_rlast,
    input  logic              s_axi_rvalid,
    input  logic              s_axi_rready
);
    function automatic logic legal_f(input logic [ADDR_W-1:0] a,
                                     input logic [2:0] sz,
                                     input logic [1:0] bu,
                                     input logic lk,
                                     input logic [LEN_W-1:0] ln);
        integer fin;
        begin
            fin = a + 4 * ln;
            legal_f = (a[1:0] == 2'b00) && (sz == 3'd2) && (bu == 2'b01) && !lk && (fin < 8);
        end
    endfunction

    wire aw_legal_w = legal_f(s_axi_awaddr, s_axi_awsize, s_axi_awburst, s_axi_awlock, s_axi_awlen);
    wire ar_legal_w = legal_f(s_axi_araddr, s_axi_arsize, s_axi_arburst, s_axi_arlock, s_axi_arlen);

    reg ok;
    initial ok = 1'b0;

    reg [31:0] mem0;
    reg [31:0] mem1;

    // write state
    reg w_active;
    reg w_beat;
    reg [LEN_W-1:0] w_len;
    reg w_a2;
    reg w_legal;
    reg w_bad;
    reg [ID_W-1:0] w_id;
    reg b_pend;
    reg [ID_W-1:0] b_id;
    reg [1:0] b_resp;

    // read state
    reg r_active;
    reg r_beat;
    reg [LEN_W-1:0] r_len;
    reg r_a2;
    reg r_legal;
    reg [ID_W-1:0] r_id;
    reg [31:0] r_data;

    // timing history
    reg aw_stall, w_stall, ar_stall, b_stall, r_stall, bhold, rhold;

    // scratch (single writer: the always block below)
    reg [31:0] nm;
    reg [1:0] widx;
    reg [1:0] ridx;
    reg mism;

    wire aw_elig = !w_active && !b_pend;

    always @(posedge clk) begin
        // reset suppresses readys
        assert(!(rst && (s_axi_awready || s_axi_wready || s_axi_arready)));

        if (ok && !rst) begin
            // ready rules
            assert(!(w_active && s_axi_awready));
            assert(!(b_pend && s_axi_awready));
            assert(!(!w_active && s_axi_wready));
            assert(!(r_active && s_axi_arready));
            // bounded ready withholding
            assert(!(aw_elig && aw_stall && !s_axi_awready));
            assert(!(w_active && w_stall && !s_axi_wready));
            assert(!(!r_active && ar_stall && !s_axi_arready));
            // B channel
            assert(!(s_axi_bvalid && !b_pend));
            assert(!(b_pend && b_stall && !s_axi_bvalid));
            assert(!(bhold && !s_axi_bvalid));
            if (s_axi_bvalid && b_pend) begin
                assert(s_axi_bid == b_id);
                assert(s_axi_bresp == b_resp);
            end
            // R channel
            assert(!(s_axi_rvalid && !r_active));
            assert(!(r_active && r_stall && !s_axi_rvalid));
            assert(!(rhold && !s_axi_rvalid));
            if (s_axi_rvalid && r_active) begin
                assert(s_axi_rid == r_id);
                assert(s_axi_rlast == (r_beat == r_len));
                assert(s_axi_rresp == (r_legal ? 2'b00 : 2'b10));
                assert(s_axi_rdata == r_data);
            end
        end

        // model update
        if (rst) begin
            ok <= 1'b1;
            mem0 <= 32'd0;
            mem1 <= 32'd0;
            w_active <= 1'b0;
            b_pend <= 1'b0;
            r_active <= 1'b0;
            aw_stall <= 1'b0;
            w_stall <= 1'b0;
            ar_stall <= 1'b0;
            b_stall <= 1'b0;
            r_stall <= 1'b0;
            bhold <= 1'b0;
            rhold <= 1'b0;
        end else if (ok) begin
            aw_stall <= aw_elig && !s_axi_awready;
            w_stall  <= w_active && !s_axi_wready;
            ar_stall <= !r_active && !s_axi_arready;
            b_stall  <= b_pend && !s_axi_bvalid;
            r_stall  <= r_active && !s_axi_rvalid;
            bhold    <= s_axi_bvalid && !s_axi_bready;
            rhold    <= s_axi_rvalid && !s_axi_rready;

            // AW
            if (s_axi_awvalid && s_axi_awready && aw_elig) begin
                w_active <= 1'b1;
                w_beat <= 1'b0;
                w_len <= s_axi_awlen;
                w_a2 <= s_axi_awaddr[2];
                w_legal <= aw_legal_w;
                w_bad <= 1'b0;
                w_id <= s_axi_awid;
            end

            // W
            if (s_axi_wvalid && s_axi_wready && w_active) begin
                mism = (s_axi_wlast != (w_beat == w_len));
                widx = {1'b0, w_a2} + {1'b0, w_beat};
                if (w_legal) begin
                    nm = (widx == 2'd0) ? mem0 : mem1;
                    if (s_axi_wstrb[0]) nm[7:0]   = s_axi_wdata[7:0];
                    if (s_axi_wstrb[1]) nm[15:8]  = s_axi_wdata[15:8];
                    if (s_axi_wstrb[2]) nm[23:16] = s_axi_wdata[23:16];
                    if (s_axi_wstrb[3]) nm[31:24] = s_axi_wdata[31:24];
                    if (widx == 2'd0) mem0 <= nm;
                    else mem1 <= nm;
                end
                if (w_beat == w_len) begin
                    w_active <= 1'b0;
                    b_pend <= 1'b1;
                    b_id <= w_id;
                    b_resp <= (w_legal && !w_bad && !mism) ? 2'b00 : 2'b10;
                end else begin
                    w_beat <= 1'b1;
                    w_bad <= w_bad | mism;
                end
            end

            // B
            if (s_axi_bvalid && s_axi_bready && b_pend) begin
                b_pend <= 1'b0;
            end

            // AR
            if (s_axi_arvalid && s_axi_arready && !r_active) begin
                r_active <= 1'b1;
                r_beat <= 1'b0;
                r_len <= s_axi_arlen;
                r_a2 <= s_axi_araddr[2];
                r_legal <= ar_legal_w;
                r_id <= s_axi_arid;
                r_data <= ar_legal_w ? (s_axi_araddr[2] ? mem1 : mem0) : 32'd0;
            end

            // R
            if (s_axi_rvalid && s_axi_rready && r_active) begin
                if (r_beat == r_len) begin
                    r_active <= 1'b0;
                end else begin
                    ridx = {1'b0, r_a2} + {1'b0, r_beat} + 2'd1;
                    r_beat <= 1'b1;
                    r_data <= r_legal ? ((ridx == 2'd1) ? mem1 : mem0) : 32'd0;
                end
            end
        end
    end
endmodule

module rtl_checker #(
    parameter integer DATA_W = 2,
    parameter integer TAG_W = 1,
    parameter integer INDEX_W = 1
) (
    input logic clk, rst, inv_valid, inv_ready,
    input logic cpu_req_valid, cpu_req_ready,
    input logic [TAG_W+INDEX_W:0] cpu_req_addr,
    input logic cpu_rsp_valid, cpu_rsp_ready,
    input logic [DATA_W-1:0] cpu_rsp_data,
    input logic mem_req_valid, mem_req_ready,
    input logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input logic mem_rsp_valid, mem_rsp_ready,
    input logic [2*DATA_W-1:0] mem_rsp_data
);
    // Phases: 0 idle (with optional rearm edge), 1 waiting for mem request transfer,
    // 2 waiting for refill, 3 waiting for CPU response offer/transfer.
    reg started;
    reg [2:0] phase;
    reg [1:0] w;
    reg off;
    reg rearm;
    reg [2:0] saddr;
    reg [1:0] exp;
    reg v0, v1, t0, t1;
    reg [3:0] d0, d1;

    wire idx = cpu_req_addr[1];
    wire hitv = idx ? v1 : v0;
    wire hitt = idx ? t1 : t0;
    wire [3:0] line = idx ? d1 : d0;
    wire hit = hitv && (hitt == cpu_req_addr[2]);
    wire [1:0] hitword = cpu_req_addr[0] ? line[3:2] : line[1:0];
    wire [1:0] refword = saddr[0] ? mem_rsp_data[3:2] : mem_rsp_data[1:0];

    always @(posedge clk) begin
        assert(!rst || (!inv_ready && !cpu_req_ready && !cpu_rsp_valid &&
                        !mem_req_valid && !mem_rsp_ready));

        if (started && !rst) begin
            case (phase)
                3'd0: begin
                    assert(cpu_req_ready == (inv_ready && !inv_valid));
                    assert(inv_ready || rearm);
                    assert(!cpu_rsp_valid && !mem_req_valid && !mem_rsp_ready);
                end
                3'd1: begin
                    assert(!inv_ready && !cpu_req_ready && !cpu_rsp_valid && !mem_rsp_ready);
                    assert(!off || mem_req_valid);
                    assert(mem_req_valid || (w < 2'd2));
                    assert(!mem_req_valid || (mem_req_addr == saddr[2:1]));
                end
                3'd2: begin
                    assert(!inv_ready && !cpu_req_ready && !cpu_rsp_valid && !mem_req_valid);
                    assert(mem_rsp_ready);
                end
                3'd3: begin
                    assert(!inv_ready && !cpu_req_ready && !mem_req_valid && !mem_rsp_ready);
                    assert(!off || cpu_rsp_valid);
                    assert(cpu_rsp_valid || (w < 2'd2));
                    assert(!cpu_rsp_valid || (cpu_rsp_data == exp));
                end
                default: begin
                end
            endcase
        end

        if (rst) begin
            started <= 1'b1;
            phase <= 3'd0;
            rearm <= 1'b0;
            off <= 1'b0;
            w <= 2'd0;
            v0 <= 1'b0;
            v1 <= 1'b0;
        end else if (started) begin
            case (phase)
                3'd0: begin
                    rearm <= 1'b0;
                    if (inv_valid && inv_ready) begin
                        v0 <= 1'b0;
                        v1 <= 1'b0;
                    end else if (cpu_req_valid && cpu_req_ready) begin
                        saddr <= cpu_req_addr;
                        w <= 2'd0;
                        off <= 1'b0;
                        if (hit) begin
                            phase <= 3'd3;
                            exp <= hitword;
                        end else begin
                            phase <= 3'd1;
                        end
                    end
                end
                3'd1: begin
                    if (mem_req_valid) begin
                        off <= 1'b1;
                        if (mem_req_ready) phase <= 3'd2;
                    end else begin
                        w <= w + 2'd1;
                    end
                end
                3'd2: begin
                    if (mem_rsp_valid && mem_rsp_ready) begin
                        if (saddr[1]) begin
                            v1 <= 1'b1;
                            t1 <= saddr[2];
                            d1 <= mem_rsp_data;
                        end else begin
                            v0 <= 1'b1;
                            t0 <= saddr[2];
                            d0 <= mem_rsp_data;
                        end
                        phase <= 3'd3;
                        w <= 2'd0;
                        off <= 1'b0;
                        exp <= refword;
                    end
                end
                3'd3: begin
                    if (cpu_rsp_valid) begin
                        off <= 1'b1;
                        if (cpu_rsp_ready) begin
                            phase <= 3'd0;
                            rearm <= 1'b1;
                        end
                    end else begin
                        w <= w + 2'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end
endmodule

module rtl_checker #(
    parameter integer DATA_W = 2,
    parameter integer TAG_W = 1,
    parameter integer INDEX_W = 1
) (
    input logic clk, rst, inv_valid, inv_ready,
    input logic cpu_req_valid, cpu_req_ready,
    input logic [TAG_W+INDEX_W:0] cpu_req_addr,
    input logic cpu_rsp_valid, cpu_rsp_ready,
    input logic [DATA_W-1:0] cpu_rsp_data,
    input logic mem_req_valid, mem_req_ready,
    input logic [TAG_W+INDEX_W-1:0] mem_req_addr,
    input logic mem_rsp_valid, mem_rsp_ready,
    input logic [2*DATA_W-1:0] mem_rsp_data
);
    // st: 0 idle, 1 miss waiting for mem request transfer, 2 waiting refill,
    //     3 cpu response pending, 4 post-response (optional rearm cycle)
    reg est = 1'b0;
    reg [2:0] st;
    reg [1:0] cnt;
    reg [1:0] saved_ix;
    reg saved_w;
    reg [1:0] exp_data;
    reg v0, v1, t0, t1;
    reg [3:0] d0, d1;

    wire a_idx = cpu_req_addr[1];
    wire a_tag = cpu_req_addr[2];
    wire a_w   = cpu_req_addr[0];
    wire sel_v = a_idx ? v1 : v0;
    wire sel_t = a_idx ? t1 : t0;
    wire [3:0] sel_d = a_idx ? d1 : d0;
    wire hit = sel_v && (sel_t == a_tag);
    wire [1:0] hit_word = a_w ? sel_d[3:2] : sel_d[1:0];

    always @(posedge clk) begin
        if (rst) begin
            assert(!inv_ready && !cpu_req_ready && !cpu_rsp_valid && !mem_req_valid && !mem_rsp_ready);
            est <= 1'b1;
            st <= 3'd0;
            cnt <= 2'd0;
            v0 <= 1'b0;
            v1 <= 1'b0;
        end else if (est) begin
            if (st == 3'd0 || st == 3'd4) begin
                assert(!cpu_rsp_valid && !mem_req_valid && !mem_rsp_ready);
                if (st == 3'd4 && !inv_ready) begin
                    assert(!cpu_req_ready);
                    st <= 3'd0;
                end else begin
                    assert(inv_ready);
                    assert(cpu_req_ready == !inv_valid);
                    if (inv_valid) begin
                        v0 <= 1'b0;
                        v1 <= 1'b0;
                        st <= 3'd0;
                    end else if (cpu_req_valid && cpu_req_ready) begin
                        cnt <= 2'd0;
                        if (hit) begin
                            st <= 3'd3;
                            exp_data <= hit_word;
                        end else begin
                            st <= 3'd1;
                            saved_ix <= cpu_req_addr[2:1];
                            saved_w <= a_w;
                        end
                    end else begin
                        st <= 3'd0;
                    end
                end
            end else if (st == 3'd1) begin
                assert(!inv_ready && !cpu_req_ready && !cpu_rsp_valid && !mem_rsp_ready);
                assert(mem_req_valid || cnt < 2'd2);
                if (mem_req_valid) begin
                    assert(mem_req_addr == saved_ix);
                    if (mem_req_ready) st <= 3'd2;
                    else cnt <= 2'd3;
                end else begin
                    cnt <= cnt + 2'd1;
                end
            end else if (st == 3'd2) begin
                assert(!inv_ready && !cpu_req_ready && !cpu_rsp_valid && !mem_req_valid);
                assert(mem_rsp_ready);
                if (mem_rsp_valid) begin
                    if (saved_ix[0]) begin
                        v1 <= 1'b1;
                        t1 <= saved_ix[1];
                        d1 <= mem_rsp_data;
                    end else begin
                        v0 <= 1'b1;
                        t0 <= saved_ix[1];
                        d0 <= mem_rsp_data;
                    end
                    exp_data <= saved_w ? mem_rsp_data[3:2] : mem_rsp_data[1:0];
                    st <= 3'd3;
                    cnt <= 2'd0;
                end
            end else if (st == 3'd3) begin
                assert(!inv_ready && !cpu_req_ready && !mem_req_valid && !mem_rsp_ready);
                assert(cpu_rsp_valid || cnt < 2'd2);
                if (cpu_rsp_valid) begin
                    assert(cpu_rsp_data == exp_data);
                    if (cpu_rsp_ready) st <= 3'd4;
                    else cnt <= 2'd3;
                end else begin
                    cnt <= cnt + 2'd1;
                end
            end
        end
    end
endmodule

module rtl_checker #(parameter integer UNIT_W = 2) (
    input logic clk, rst, in_valid, in_ready,
    input logic [4*UNIT_W-1:0] in_data,
    input logic out_valid, out_ready,
    input logic [3*UNIT_W-1:0] out_data
);
    localparam integer BW = 8*UNIT_W;

    reg known;
    reg [BW-1:0] sbuf;
    integer cnt;
    reg prev_stall;
    reg prev_il_low;
    reg prev_ov_low;

    initial begin
        known = 1'b0;
        sbuf = 0;
        cnt = 0;
        prev_stall = 1'b0;
        prev_il_low = 1'b0;
        prev_ov_low = 1'b0;
    end

    integer c_after;
    reg elig;
    reg oxfer;
    reg ixfer;
    reg [BW-1:0] base;
    reg [BW-1:0] ext;
    integer sh;

    always @(posedge clk) begin
        oxfer = out_valid && out_ready;
        ixfer = in_valid && in_ready;
        c_after = cnt - (oxfer ? 3 : 0);
        elig = (c_after + 4) <= 8;

        // reset: no ready
        assert (!(rst && in_ready));

        if (known && !rst) begin
            // output validity / data
            assert (!out_valid || (cnt >= 3));
            assert (!out_valid || (out_data == sbuf[3*UNIT_W-1:0]));
            // stalled offer persistence
            assert (!prev_stall || out_valid);
            // input room
            assert (!in_ready || elig);
            // bubble bounds
            assert (!(prev_il_low && elig) || in_ready);
            assert (!(prev_ov_low && (cnt >= 3)) || out_valid);
        end

        // state update
        if (rst) begin
            known = 1'b1;
            cnt = 0;
            sbuf = 0;
            prev_stall = 1'b0;
            prev_il_low = 1'b0;
            prev_ov_low = 1'b0;
        end else if (known) begin
            prev_stall = out_valid && !out_ready;
            prev_il_low = elig && !in_ready;
            prev_ov_low = (cnt >= 3) && !out_valid;
            base = sbuf;
            if (oxfer) begin
                base = sbuf >> (3*UNIT_W);
            end
            if (c_after < 0) c_after = 0;
            if (ixfer) begin
                ext = {{(BW-4*UNIT_W){1'b0}}, in_data};
                sh = UNIT_W * c_after;
                base = base | (ext << sh);
                c_after = c_after + 4;
            end
            sbuf = base;
            cnt = c_after;
        end
    end
endmodule

module rtl_checker #(parameter integer UNIT_W = 2) (
    input logic clk, rst, in_valid, in_ready,
    input logic [4*UNIT_W-1:0] in_data,
    input logic out_valid, out_ready,
    input logic [3*UNIT_W-1:0] out_data
);
    localparam integer BW = 8*UNIT_W;

    reg known;
    integer cnt;
    reg [BW-1:0] sbuf;
    reg prev_in_bubble;
    reg prev_out_bubble;
    reg prev_stall;

    // scratch (single writer: the clocked block)
    reg oxfer;
    reg ixfer;
    reg elig;
    integer cnt2;
    reg [BW-1:0] tmp;
    reg [BW-1:0] ins;

    initial begin
        known = 1'b0;
        cnt = 0;
        sbuf = {BW{1'b0}};
        prev_in_bubble = 1'b0;
        prev_out_bubble = 1'b0;
        prev_stall = 1'b0;
    end

    always @(posedge clk) begin
        oxfer = out_valid && out_ready;
        ixfer = in_valid && in_ready;
        cnt2 = cnt - (oxfer ? 3 : 0);
        elig = ((cnt2 + 4) <= 8);

        // reset: no ready
        assert(!(rst && in_ready));

        if (known && !rst) begin
            // output offer needs >= 3 retained units
            assert(!out_valid || (cnt >= 3));
            // data check
            assert(!out_valid || (out_data == sbuf[3*UNIT_W-1:0]));
            // stalled output must persist
            assert(!prev_stall || out_valid);
            // no ready without room
            assert(!in_ready || elig);
            // bounded input bubble
            assert(!(prev_in_bubble && elig && !in_ready));
            // bounded output bubble
            assert(!(prev_out_bubble && (cnt >= 3) && !out_valid));
        end

        if (rst) begin
            known <= 1'b1;
            cnt <= 0;
            sbuf <= {BW{1'b0}};
            prev_in_bubble <= 1'b0;
            prev_out_bubble <= 1'b0;
            prev_stall <= 1'b0;
        end else if (known) begin
            tmp = oxfer ? (sbuf >> (3*UNIT_W)) : sbuf;
            ins = {{(4*UNIT_W){1'b0}}, in_data};
            ins = ins << (cnt2 * UNIT_W);
            if (ixfer) begin
                tmp = tmp | ins;
                cnt <= cnt2 + 4;
            end else begin
                cnt <= cnt2;
            end
            sbuf <= tmp;
            prev_in_bubble <= elig && !in_ready;
            prev_out_bubble <= (cnt >= 3) && !out_valid;
            prev_stall <= out_valid && !out_ready;
        end else begin
            prev_in_bubble <= 1'b0;
            prev_out_bubble <= 1'b0;
            prev_stall <= 1'b0;
        end
    end
endmodule
